import {surface,clear,grid,text} from './shared.js';
export function overlapBlock(previous,moving,tolerance=6){if(Math.abs(previous.x-moving.x)<=tolerance)return {x:previous.x,w:previous.w,perfect:true};const x=Math.max(previous.x,moving.x),w=Math.min(previous.x+previous.w,moving.x+moving.w)-x;return {x,w:Math.max(0,w),perfect:false};}
export function createStack(mount,api){
 const s=surface(mount),{ctx,view}=s;let blocks=[],moving,dir=1,speed=105,height=0,running=false,preview=true,flash=0,perfect=false;
 function reset(isPreview=false){preview=isPreview;height=0;speed=105;dir=1;flash=0;running=!preview;blocks=preview?Array.from({length:9},(_,i)=>({x:74+i*4,w:235-i*5})):[{x:70,w:240}];moving={x:preview?56:4,w:blocks.at(-1).w};draw();}
 function block(x,y,w,hue,factor,offset){x=offset+x*factor;w*=factor;const d=24*factor,thick=18*factor;ctx.fillStyle=`hsl(${hue} 53% 42%)`;ctx.fillRect(x,y,w,thick);ctx.fillStyle=`hsl(${hue} 58% 26%)`;ctx.beginPath();ctx.moveTo(x+w,y);ctx.lineTo(x+w+d,y-d*.65);ctx.lineTo(x+w+d,y+thick-d*.65);ctx.lineTo(x+w,y+thick);ctx.fill();ctx.fillStyle=`hsl(${hue} 76% 70%)`;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x+d,y-d*.65);ctx.lineTo(x+w+d,y-d*.65);ctx.lineTo(x+w,y);ctx.fill();}
 function draw(){clear(ctx);grid(ctx,view);const f=Math.min((view.width-28)/400,view.field.h/350),offset=(view.width-400*f)/2,base=view.field.y+view.field.h-28*f,step=25*f,count=Math.max(5,Math.floor((view.field.h-65*f)/step));const shown=blocks.slice(-count);ctx.strokeStyle='#a9da7e16';ctx.beginPath();ctx.ellipse(view.width/2,base+27*f,170*f,25*f,0,0,Math.PI*2);ctx.stroke();shown.forEach((b,i)=>block(b.x,base-i*step,b.w,100-i%12*2,f,offset));block(moving.x,base-shown.length*step-15*f,moving.w,79,f,offset);if(flash>0)text(ctx,perfect?'PERFECT':'NICE DROP',view.width/2,view.field.y+25,18,'#d1ff8a',700);}
 function drop(){if(!running)return;const r=overlapBlock(blocks.at(-1),moving);if(r.w<=0){running=false;api.finish('One block too far.',`${height} blocks high. Take it from the top.`);return;}blocks.push({x:r.x,w:r.w});height++;api.score(height);perfect=r.perfect;flash=.65;dir=height%2===0?1:-1;moving={x:dir===1?4:370-r.w,w:r.w};speed=Math.min(235,105+height*7);if(blocks.length>80)blocks.shift();draw();}
 reset(true);return {start(){reset();api.score(0)},tick(dt){if(running||preview){moving.x+=dir*(preview?40:speed)*dt;if(moving.x<4){moving.x=4;dir=1}if(moving.x+moving.w>370){moving.x=370-moving.w;dir=-1}flash=Math.max(0,flash-dt)}draw()},action:drop,tap:drop,destroy(){running=false;s.destroy()}};
}
